import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        if (n <= 0) {
            sc.close();
            return;
        }

        List<String> elements = new ArrayList<>();
        sc.nextLine();
        for (int i = 0; i < n; i++) {
            if (sc.hasNextLine()) {
                String line = sc.nextLine().trim();
                if (line.length() == 0) {
                    continue;
                }
                elements.add(line);
            }
        }

        if (elements.size() == 0) {
            sc.close();
            return;
        }

        MaxFinder<String> maxFinder = new MaxFinder<>();
        String maxElement = maxFinder.findMax(elements);
        System.out.println("Maximum: " + maxElement);
        sc.close();
    }
}

class MaxFinder<T extends Comparable<T>> {
    public T findMax(List<T> list) {
        if (list == null || list.size() == 0) {
            return null;
        }
        T max = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            if (list.get(i).compareTo(max) > 0) {
                max = list.get(i);
            }
        }
        return max;
    }
}
